body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  color: #111827;
  background: transparent;
}

.heatmap {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 18px;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  overflow: hidden;
}

.head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5e7eb;
}

.head span {
  display: block;
  color: #2563eb;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

h2 {
  margin: 4px 0;
  font-size: 22px;
}

p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.count {
  min-width: 44px;
  height: 38px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: #111827;
  color: white;
  font-weight: 900;
}

.warehouse-grid {
  height: calc(100% - 102px);
  overflow: auto;
  padding: 14px 2px 8px;
  display: grid;
  grid-template-columns: repeat(3, minmax(190px, 1fr));
  gap: 12px;
}

.card {
  border: 1px solid #e5e7eb;
  border-left: 7px solid #16a34a;
  border-radius: 9px;
  padding: 13px;
  background: #fff;
  cursor: pointer;
}

.card:hover {
  border-color: #14b8a6;
  background: #f0fdfa;
}

.card.warning {
  border-left-color: #f59e0b;
}

.card.danger {
  border-left-color: #ef4444;
}

.card-top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.code {
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
}

.name {
  margin-top: 3px;
  font-size: 15px;
  font-weight: 900;
}

.badge {
  height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
  background: #dcfce7;
  color: #166534;
}

.card.warning .badge {
  background: #fef3c7;
  color: #92400e;
}

.card.danger .badge {
  background: #fee2e2;
  color: #991b1b;
}

.value {
  margin-top: 12px;
  padding: 10px;
  border-radius: 8px;
  background: #f8fafc;
}

.value span {
  display: block;
  color: #64748b;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 900;
}

.value strong {
  display: block;
  margin-top: 4px;
  font-size: 19px;
}

.stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  margin-top: 10px;
}

.stat {
  border: 1px solid #e5e7eb;
  border-radius: 7px;
  padding: 8px;
}

.stat span {
  display: block;
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.stat strong {
  display: block;
  margin-top: 3px;
  font-size: 15px;
}

.empty {
  grid-column: 1/-1;
  padding: 26px;
  border: 1px dashed #cbd5e1;
  border-radius: 8px;
  text-align: center;
  color: #64748b;
}

.foot {
  padding-top: 8px;
  border-top: 1px solid #e5e7eb;
  color: #64748b;
  font-size: 11px;
}

@media (max-width: 900px) {
  .warehouse-grid {
    grid-template-columns: 1fr;
  }
}

