function money(value) {
  return Number(value || 0).toFixed(2);
}
function qty(value) {
  return Number(value || 0).toFixed(2);
}
function esc(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}
function statusLabel(value) {
  if (value === "danger") return "Critical";
  if (value === "warning") return "Watch";
  return "Healthy";
}
function openWarehouse(index) {
  const warehouses = appsmith.model?.warehouses || [];
  const selected = warehouses[index] || {};
  appsmith.updateModel({
    selectedWarehouse: selected
  });
  appsmith.triggerEvent("onWarehouseOpen");
}
function render(model = {}) {
  const warehouses = model.warehouses || [];
  const root = document.getElementById("warehouseGrid");
  document.getElementById("warehouseCount").innerText = warehouses.length;
  document.getElementById("generatedAt").innerText = "Updated: " + (model.generatedAt || "");
  if (!root) return;
  if (!warehouses.length) {
    root.innerHTML = `<div class="empty">No warehouse data available.</div>`;
    return;
  }
  root.innerHTML = warehouses.map((w, index) => `
    <div class="card ${esc(w.healthStatus || "good")}" onclick="openWarehouse(${index})">
      <div class="card-top">
        <div>
          <div class="code">${esc(w.warehouseCode || "")}</div>
          <div class="name">${esc(w.warehouseName || "")}</div>
        </div>
        <div class="badge">${statusLabel(w.healthStatus)}</div>
      </div>

      <div class="value">
        <span>Stock Value</span>
        <strong>${money(w.stockValue)} EUR</strong>
      </div>

      <div class="stats">
        <div class="stat">
          <span>Qty</span>
          <strong>${qty(w.stockQuantity)}</strong>
        </div>
        <div class="stat">
          <span>Low Stock</span>
          <strong>${w.lowStockItems || 0}</strong>
        </div>
        <div class="stat">
          <span>Tasks</span>
          <strong>${w.openTasks || 0}</strong>
        </div>
        <div class="stat">
          <span>Transfers</span>
          <strong>${Number(w.incomingTransfers || 0) + Number(w.outgoingTransfers || 0)}</strong>
        </div>
      </div>
    </div>
  `).join("");
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

